  "Front_Box_Jump":{n:"Bật nhảy lên bục phía trước (Box Jump)",g:"Đứng trước bục, hạ người, vung tay và bật lên bục, tiếp đất mềm. Bước xuống. Bục vừa sức."},
  "Front_Cable_Raise":{n:"Nâng cáp trước mặt (Cable Front Raise)",g:"Đứng quay lưng với ròng rọc thấp, cầm cáp giữa hai chân. Nâng tay thẳng ra trước lên ngang vai, rồi hạ chậm. Không ngả người."},
